119	  private static <E extends @Nullable Object> int lastPresentIndex(
120	      Comparator<? super E> comparator,
121	      @ParametricNullness E key,
122	      List<? extends E> list,
123	      int foundIndex) {
124	    // Of course, we have to use binary search to find the precise breakpoint...
125	    int lower = foundIndex;
126	    int upper = list.size() - 1;
127	    // Everything between lower and upper inclusive compares at >= 0.
128	    while (lower < upper) {
129	      int middle = (lower + upper + 1) >>> 1;
130	      int c = comparator.compare(list.get(middle), key);
131	      if (c > 0) {
132	        upper = middle - 1;
133	      } else { // c == 0
134	        lower = middle;
135	      }
136	    }
137	    return lower;
138	  }
