144	      int foundIndex) {
145	    // Of course, we have to use binary search to find the precise breakpoint...
146	    int lower = 0;
147	    int upper = foundIndex;
148	    // Everything between lower and upper inclusive compares at <= 0.
149	    while (lower < upper) {
150	      int middle = (lower + upper) >>> 1;
151	      int c = comparator.compare(list.get(middle), key);
152	      if (c < 0) {
153	        lower = middle + 1;
154	      } else { // c == 0
155	        upper = middle;
156	      }
157	    }
158	    return lower;
159	  }
