33	  /**
34	   * Returns {@code true} if {@code elements} is a sorted collection using an ordering equivalent to
35	   * {@code comparator}.
36	   */
37	  public static boolean hasSameComparator(Comparator<?> comparator, Iterable<?> elements) {
38	    checkNotNull(comparator);
39	    checkNotNull(elements);
40	    Comparator<?> comparator2 = comparatorOf(elements);
41	    return comparator2 != null && comparator.equals(comparator2);
42	  }
43	
44	  @SuppressWarnings("unchecked")
45	  // if sortedSet.comparator() is null, the set must be naturally ordered
46	  public static <E extends @Nullable Object> Comparator<? super E> comparator(
47	      SortedSet<E> sortedSet) {
48	    Comparator<? super E> result = sortedSet.comparator();
49	    if (result == null) {
50	      result = (Comparator<? super E>) Ordering.natural();
51	    }
52	    return result;
53	  }
54	
55	  private static @Nullable Comparator<?> comparatorOf(Iterable<?> elements) {
56	    if (elements instanceof SortedSet) {
57	      return comparator((SortedSet<?>) elements);
58	    } else if (elements instanceof SortedIterable) {
59	      return ((SortedIterable<?>) elements).comparator();
60	    }
61	    return null;
62	  }
